# Step 1 & 2: Filter results for the 'Australian Grand Prix' in 2009 and project driverids
drivers_in_race = formula_1.result.WHERE(
    (formula_1.result.race.name == 'Australian Grand Prix') & (formula_1.result.race.year == 2009)
).CALCULATE(
    driver_id_val=driverid
)

# Step 3: Calculate the number of distinct driverids from the filtered results
num_drivers_australian_gp_2009 = GRAPH.CALCULATE(
    num_drivers=NDISTINCT(drivers_in_race.driver_id_val)
)

winning_drivers_first_names = formula_1.driverstanding.WHERE(
    wins > 0
).driver.PARTITION(
    name="unique_forenames",
    by=forename
).CALCULATE(
    first_name=forename
)

# Filter driver standings to find drivers who won (position 1) and had more than 20 points.
winning_drivers_info = formula_1.driverstanding.WHERE(
    (position == 1) & (points > 20)
).CALCULATE(
    # Access the driver's first name from the joined 'driver' collection
    driver_first_name=driver.forename
)

# Partition by driver_first_name to get distinct first names
distinct_winning_drivers = winning_drivers_info.PARTITION(
    name="drivers", by=driver_first_name
).CALCULATE(
    first_name=driver_first_name
)

races_in_spain_after_2017 = formula_1.race.WHERE(
