)

distinct_winning_drivers = formula_1.driverstanding.WHERE(
    (formula_1.driverstanding.position == 1) & 
    (formula_1.driverstanding.wins == 1)
).CALCULATE(
    # Calculate the driver's forename to make it available as a scalar field for grouping.
    driver_forename_calc=formula_1.driverstanding.driver.forename
).GROUP_BY(
    # Group by the calculated forename to get distinct values.
    by=driver_forename_calc
).CALCULATE(
    # Select the forename from the grouped results, renaming it to 'forename'.
    forename=driver_forename_calc
)

races_by_time_condition = formula_1.race.CALCULATE(
    # Combine date and time strings into a full datetime string, then parse it
    # This ensures proper datetime object for hour extraction.
    full_race_datetime=DATETIME(JOIN_STRINGS(' ', date, time))
).WHERE(
    # Filter based on the hour component of the parsed datetime object
    (HOUR(full_race_datetime) > 12) | (HOUR(full_race_datetime) < 9)
).CALCULATE(
    race_name=name
)

# Step 1: Find the maximum pit stop duration (as a string) in race with id 841
max_duration_race_841 = formula_1.pitstop.WHERE(
    raceid == 841
).CALCULATE(
    max_duration_str=MAX(duration)
).SINGULAR().max_duration_str

# Step 2 & 3: Find distinct driver ID and stop number for pit stops shorter than the max duration from race 841
result = formula_1.pitstop.WHERE(
    duration < max_duration_race_841
).CALCULATE(
    driver_id=driverid,
    stop_number=stop
).DISTINCT()

races_per_driver = formula_1.driver.CALCULATE(
    driver_id=driverid,
    num_races=COUNT(result)
).WHERE(
    num_races <= 30
).CALCULATE(
    driver_id=driver_id,
    num_races=num_races
)

max_lap_speed_by_race = formula_1.result.WHERE(
    race.year > 2014
).CALCULATE(
    race_name=race.name,
    race_year_val=race.year,  # Original year for aggregation
    speed=DECIMAL(fastestlapspeed) # Converted speed for max aggregation
).PARTITION(
    name="race_laps",
    by=race_name # Grouping only by race name as per feedback
).CALCULATE(
    race_name=race_name,
    race_year=MIN(race_laps.race_year_val), # Aggregate year for each race name
    max_fastest_lap_speed=MAX(race_laps.speed)
).ORDER_BY(
    race_year.ASC()
)

average_fastest_lap_speed_per_race = formula_1.race.WHERE(
    year > 2014
).CALCULATE(
    race_name=name,
    race_year=year,
    avg_lap_speed=SUM(result.fastestlapspeed) / COUNT(result.fastestlapspeed)
).ORDER_BY(
    race_year.ASC()
)

