max_fastest_lap_speed_monaco_2008 = formula_1.result.WHERE(
    (formula_1.result.race.name == 'Monaco Grand Prix') &
    (formula_1.result.race.year == 2008)
).CALCULATE(
    # Explicitly cast the string 'fastestlapspeed' to DECIMAL for correct numerical aggregation.
    numeric_fastestlapspeed=DECIMAL(fastestlapspeed)
).AGGREGATE(
    # Use AGGREGATE to perform the scalar MAX aggregation on the numeric field.
    max_speed=MAX(numeric_fastestlapspeed)
)

