cities_without_customers = address.PARTITION(
    name="city_level",
    by=city
).CALCULATE(
    city_name=city,
    # Count all customer_address records linked to any address within this city group.
    # If this count is 0, it means no customer has ever lived in any address in this city.
    num_customer_addresses = COUNT(address.customer_address)
).WHERE(
    num_customer_addresses == 0
).CALCULATE(
    city=city_name
)

