latest_contact_date = customer.WHERE(
    customer_name == "Tillman Ernser"
).customer_contact_channel.CALCULATE(
    channel_rank=RANKING(by=active_to_date.DESC(), per="customer")
).WHERE(
    channel_rank == 1
).SINGULAR().CALCULATE(
