shut_down_plants_by_country = GeoNuclearData.nuclear_power_plants.WHERE(
    Status == "Shut down"
).PARTITION(
    name="countries", by=Country
).CALCULATE(
    country_name=Country,
    num_shut_down_plants=COUNT(nuclear_power_plants)
).TOP_K(
    1, by=num_shut_down_plants.DESC()
)

country_capacities = GeoNuclearData.nuclear_power_plants.PARTITION(
    name="countries", 
    by=Country
).CALCULATE(
    country_name=Country,
    total_capacity=SUM(nuclear_power_plants.Capacity)
)

country_with_least_capacity = country_capacities.TOP_K(1, by=total_capacity.ASC()).CALCULATE(
    country_name=country_name
)

country_most_shut_down = GeoNuclearData.nuclear_power_plants.WHERE(
    Status == "Shut down"
).PARTITION(
    name="countries",
    by=(Country)
).CALCULATE(
    country_name=Country,
    shut_down_count=COUNT(nuclear_power_plants)
).TOP_K(1, by=shut_down_count.DESC())

max_capacity_plant_status = GeoNuclearData.nuclear_power_plants.WHERE(
    Country == "United States"
).CALCULATE(
    plant_status=Status,
    plant_capacity=Capacity
).TOP_K(1, by=plant_capacity.DESC()).CALCULATE(
    current_status=plant_status
)

under_construction_plants = GeoNuclearData.nuclear_power_plants.WHERE(
    Status == "Under Construction"
)

country_plant_counts = under_construction_plants.PARTITION(
    name="countries", by=Country
).CALCULATE(
    country_name=Country,
    plant_count=COUNT(nuclear_power_plants)
)

result = country_plant_counts.TOP_K(1, by=plant_count.DESC()).CALCULATE(
    country_name,
    plant_count
)

operational_plants_by_country = GeoNuclearData.nuclear_power_plants.WHERE(
    Status == 'Operational'
).PARTITION(
    name="countries_group", 
    by=Country
).CALCULATE(
    country_name=Country,
    num_operational_plants=COUNT(nuclear_power_plants)
).TOP_K(10, by=num_operational_plants.DESC())

